public class FibonacciDP {
    public long fib(int n) {
        if (n <= 1) return n;
        long[] dp = new long[n + 1];
        dp[0] = 0; dp[1] = 1;
        for (int i = 2; i <= n; i++)
            dp[i] = dp[i-1] + dp[i-2];
        return dp[n];
    }
    // Space-optimized O(1) version
    public long fibOptimized(int n) {
        if (n <= 1) return n;
        long a = 0, b = 1;
        for (int i = 2; i <= n; i++) { long c = a + b; a = b; b = c; }
        return b;
    }
    public static void main(String[] args) {
        FibonacciDP f = new FibonacciDP();
        for (int i = 0; i <= 10; i++) System.out.print(f.fib(i) + " ");
    }
}

